"""
改进的会议安排脚本
"""

import json
import itertools
from datetime import datetime, timedelta

# 会议定义
meetings = [
    {"id": 1, "name": "Product Review", "attendees": ["Alice", "Bob", "Carol"]},
    {"id": 2, "name": "Tech Design", "attendees": ["Bob", "David", "Eve"]},
    {"id": 3, "name": "Budget Planning", "attendees": ["Alice", "Frank", "Grace"]},
    {"id": 4, "name": "Team Sync", "attendees": ["Carol", "David", "Henry"]},
    {"id": 5, "name": "Client Demo", "attendees": ["Eve", "Frank", "Henry"]},
]

# 工作时间：9:00-18:00（9小时）
work_start = datetime.strptime("09:00", "%H:%M")
work_end = datetime.strptime("18:00", "%H:%M")
meeting_duration = 60  # 分钟
min_interval = 30  # 分钟

# 生成可能的时间槽（每30分钟）
time_slots = []
current = work_start
while current + timedelta(minutes=meeting_duration) <= work_end:
    time_slots.append(current)
    current += timedelta(minutes=30)

def time_str(t):
    return t.strftime("%H:%M")

def check_schedule(schedule):
    """检查调度是否满足所有约束"""
    # 1. 每个人同一时间只能参加一个会议
    for i, m1 in enumerate(schedule):
        for j, m2 in enumerate(schedule):
            if i == j:
                continue
            # 检查时间重叠
            m1_start = m1["start"]
            m1_end = m1_start + timedelta(minutes=meeting_duration)
            m2_start = m2["start"]
            m2_end = m2_start + timedelta(minutes=meeting_duration)

            # 如果时间重叠
            if not (m1_end <= m2_start or m2_end <= m1_start):
                # 检查参会人员冲突
                common_attendees = set(m1["attendees"]) & set(m2["attendees"])
                if common_attendees:
                    return False, f"人员冲突: {common_attendees} 同时参加 {m1['name']} 和 {m2['name']}"

    # 2. Alice 必须在下午（14:00后）参加 Product Review
    for meeting in schedule:
        if meeting["name"] == "Product Review":
            if meeting["start"].hour < 14:
                return False, "Product Review 必须在14:00后（Alice约束）"

    # 3. Bob 在 11:00-14:00 之间不可用
    bob_unavailable_start = datetime.strptime("11:00", "%H:%M")
    bob_unavailable_end = datetime.strptime("14:00", "%H:%M")
    for meeting in schedule:
        if "Bob" in meeting["attendees"]:
            meeting_start = meeting["start"]
            meeting_end = meeting_start + timedelta(minutes=meeting_duration)
            # 检查会议是否与Bob不可用时间段重叠
            if (meeting_start < bob_unavailable_end and 
                meeting_end > bob_unavailable_start):
                return False, f"Bob 在11:00-14:00不可用，但参加了 {meeting['name']}"

    # 4. Eve 必须在上午（12:00前）参加 Client Demo
    noon = datetime.strptime("12:00", "%H:%M")
    for meeting in schedule:
        if meeting["name"] == "Client Demo":
            if meeting["start"].hour >= 12:
                return False, "Client Demo 必须在12:00前（Eve约束）"

    # 5. Budget Planning 必须在 Tech Design 之前
    budget_planning_time = None
    tech_design_time = None
    for meeting in schedule:
        if meeting["name"] == "Budget Planning":
            budget_planning_time = meeting["start"]
        elif meeting["name"] == "Tech Design":
            tech_design_time = meeting["start"]

    if budget_planning_time is None or tech_design_time is None:
        return False, "缺少Budget Planning或Tech Design"

    if budget_planning_time >= tech_design_time:
        return False, "Budget Planning 必须在 Tech Design 之前"

    # 6. 每个会议之间至少间隔30分钟（对于同一会议室）
    # 这将在会议室分配后检查

    # 7. 会议室只有2个，不能同时开3个会议
    # 按时间分组检查同时进行的会议
    time_groups = {}
    for meeting in schedule:
        key = meeting["start"]
        if key not in time_groups:
            time_groups[key] = 0
        time_groups[key] += 1

    for time, count in time_groups.items():
        if count > 2:
            return False, f"在 {time_str(time)} 有 {count} 个会议同时进行，超过2个会议室"

    return True, "所有约束满足"

def assign_rooms_properly(schedule):
    """正确分配会议室A或B"""
    # 按开始时间排序
    sorted_schedule = sorted(schedule, key=lambda x: x["start"])

    # 初始化会议室分配
    for meeting in sorted_schedule:
        meeting["room"] = None

    # 对于每个时间点，分配可用的会议室
    time_points = sorted(set(m["start"] for m in sorted_schedule))

    # 跟踪会议室占用时间
    room_a_busy_until = work_start
    room_b_busy_until = work_start

    for meeting in sorted_schedule:
        meeting_start = meeting["start"]
        meeting_end = meeting_start + timedelta(minutes=meeting_duration)

        # 检查会议室A是否可用
        if room_a_busy_until <= meeting_start:
            meeting["room"] = "A"
            room_a_busy_until = meeting_end
        # 检查会议室B是否可用
        elif room_b_busy_until <= meeting_start:
            meeting["room"] = "B"
            room_b_busy_until = meeting_end
        else:
            # 两个会议室都忙，需要调整时间
            return None

    return sorted_schedule

def find_valid_schedule():
    """寻找有效的调度方案"""
    # 使用启发式方法：
    # 1. 先安排有严格时间约束的会议
    # 2. 再安排其他会议

    # 尝试不同的时间组合
    for i1, start1 in enumerate(time_slots):
        for i2, start2 in enumerate(time_slots):
            if i2 <= i1:
                continue
            for i3, start3 in enumerate(time_slots):
                if i3 <= i2:
                    continue
                for i4, start4 in enumerate(time_slots):
                    if i4 <= i3:
                        continue
                    for i5, start5 in enumerate(time_slots):
                        if i5 <= i4:
                            continue

                        # 尝试所有会议排列
                        times = [start1, start2, start3, start4, start5]

                        for perm in itertools.permutations(meetings, 5):
                            schedule = []
                            for i, meeting in enumerate(perm):
                                schedule.append({
                                    "id": meeting["id"],
                                    "name": meeting["name"],
                                    "attendees": meeting["attendees"],
                                    "start": times[i],
                                })

                            # 检查基本约束
                            valid, msg = check_schedule(schedule)
                            if valid:
                                # 分配会议室
                                schedule_with_rooms = assign_rooms_properly(schedule)
                                if schedule_with_rooms is not None:
                                    # 检查会议室分配后的间隔
                                    # 确保同一会议室会议之间至少30分钟间隔
                                    room_schedules = {"A": [], "B": []}
                                    for meeting in schedule_with_rooms:
                                        room = meeting["room"]
                                        room_schedules[room].append({
                                            "name": meeting["name"],
                                            "start": meeting["start"],
                                            "end": meeting["start"] + timedelta(minutes=meeting_duration)
                                        })

                                    # 检查每个会议室的间隔
                                    ok = True
                                    for room, meetings_in_room in room_schedules.items():
                                        meetings_in_room.sort(key=lambda x: x["start"])
                                        for i in range(len(meetings_in_room)-1):
                                            m1_end = meetings_in_room[i]["end"]
                                            m2_start = meetings_in_room[i+1]["start"]
                                            gap = (m2_start - m1_end).total_seconds() / 60
                                            if gap < min_interval:
                                                ok = False
                                                break
                                        if not ok:
                                            break

                                    if ok:
                                        return schedule_with_rooms

    return None

def main():
    print("寻找满足所有约束的会议安排...")

    # 寻找有效调度
    schedule = find_valid_schedule()

    if schedule is None:
        print("未找到满足所有约束的安排")
        return False

    print("\n找到满足所有约束的安排:")
    print("=" * 60)

    # 格式化输出
    output_schedule = []
    for meeting in sorted(schedule, key=lambda x: x["start"]):
        meeting_end = meeting["start"] + timedelta(minutes=meeting_duration)
        meeting_info = {
            "name": meeting["name"],
            "start": time_str(meeting["start"]),
            "end": time_str(meeting_end),
            "room": meeting["room"],
            "attendees": meeting["attendees"]
        }
        output_schedule.append(meeting_info)

        print(f"会议: {meeting['name']}")
        print(f"  时间: {time_str(meeting['start'])} - {time_str(meeting_end)}")
        print(f"  会议室: {meeting['room']}")
        print(f"  参会人员: {', '.join(meeting['attendees'])}")
        print()

    # 保存到JSON文件
    with open("schedule.json", "w") as f:
        json.dump(output_schedule, f, indent=2)

    print(f"\n调度已保存到 schedule.json")

    # 验证所有约束
    print("\n详细约束检查:")
    print("-" * 40)

    # 1. Alice下午参加Product Review
    for m in schedule:
        if m["name"] == "Product Review":
            print(f"✓ Product Review在{time_str(m['start'])}，Alice在下午参加: {m['start'].hour >= 14}")

    # 2. Bob 11:00-14:00不可用
    bob_ok = True
    for m in schedule:
        if "Bob" in m["attendees"]:
            start = m["start"]
            end = start + timedelta(minutes=60)
            bob_start = datetime.strptime("11:00", "%H:%M")
            bob_end = datetime.strptime("14:00", "%H:%M")
            if not (end <= bob_start or start >= bob_end):
                bob_ok = False
                print(f"✗ Bob在11:00-14:00参加了{m['name']} ({time_str(start)}-{time_str(end)})")
    if bob_ok:
        print(f"✓ Bob在11:00-14:00未安排会议")

    # 3. Eve上午参加Client Demo
    for m in schedule:
        if m["name"] == "Client Demo":
            print(f"✓ Client Demo在{time_str(m['start'])}，Eve在上午参加: {m['start'].hour < 12}")

    # 4. Budget Planning在Tech Design之前
    bp_time = None
    td_time = None
    for m in schedule:
        if m["name"] == "Budget Planning":
            bp_time = m["start"]
        elif m["name"] == "Tech Design":
            td_time = m["start"]
    if bp_time and td_time:
        print(f"✓ Budget Planning({time_str(bp_time)})在Tech Design({time_str(td_time)})之前: {bp_time < td_time}")

    # 5. 会议室限制
    time_counts = {}
    for m in schedule:
        key = time_str(m["start"])
        time_counts[key] = time_counts.get(key, 0) + 1

    print(f"\n同时进行的会议数量(最多2个):")
    all_ok = True
    for time, count in sorted(time_counts.items()):
        ok = count <= 2
        if not ok:
            all_ok = False
        print(f"  {time}: {count}个会议 {'✓' if ok else '✗'}")

    # 6. 会议间隔检查
    print(f"\n会议室使用情况:")
    for room in ["A", "B"]:
        room_meetings = [m for m in schedule if m["room"] == room]
        room_meetings.sort(key=lambda x: x["start"])
        print(f"  会议室{room}: {len(room_meetings)}个会议")
        for i, m in enumerate(room_meetings):
            start = m["start"]
            end = start + timedelta(minutes=60)
            print(f"    {time_str(start)}-{time_str(end)}: {m['name']}")

    # 7. 人员冲突检查
    print(f"\n人员冲突检查:")
    conflict_free = True
    for i, m1 in enumerate(schedule):
        for j, m2 in enumerate(schedule):
            if i >= j:
                continue
            m1_start = m1["start"]
            m1_end = m1_start + timedelta(minutes=60)
            m2_start = m2["start"]
            m2_end = m2_start + timedelta(minutes=60)

            # 检查时间重叠
            if not (m1_end <= m2_start or m2_end <= m1_start):
                common = set(m1["attendees"]) & set(m2["attendees"])
                if common:
                    conflict_free = False
                    print(f"✗ {m1['name']}和{m2['name']}时间重叠，共同参会人员: {common}")

    if conflict_free:
        print(f"✓ 无人员冲突")

    return True

if __name__ == "__main__":
    main()"}}
